package com.yongdrel.payment_qr_service.function;
import com.yongdrel.payment_qr_service.application.port.*; import org.junit.jupiter.api.*; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class PaymentQrFunctionTest{
 @Test void generatesQrOnlyFromTrustedMatchingDetails(){UUID t=UUID.randomUUID(),o=UUID.randomUUID(),id=UUID.randomUUID();OrderTrustPort order=mock(OrderTrustPort.class);TenantPaymentDetailsPort tenant=mock(TenantPaymentDetailsPort.class);when(order.get(id,t)).thenReturn(new OrderTrustPort.OrderDetails(id,t,new BigDecimal("25.00"),"BTN","AWAITING_PAYMENT","REF-1"));when(tenant.get(t,o)).thenReturn(new TenantPaymentDetailsPort.PaymentDetails(t,o,"Bank","ACC","Pay exact amount"));var result=new PaymentQrFunction(order,tenant).generatePaymentQr().apply(new PaymentQrFunction.PaymentQrRequest(t,o,id,new BigDecimal("25.00"),"BTN","REF-1"));assertTrue(result.qrImageDataUri().startsWith("data:image/png;base64,"));assertTrue(result.qrData().contains("REF-1"));}
 @Test void failsClosedWhenUpstreamUnavailable(){OrderTrustPort order=mock(OrderTrustPort.class);TenantPaymentDetailsPort tenant=mock(TenantPaymentDetailsPort.class);UUID id=UUID.randomUUID(),t=UUID.randomUUID();assertThrows(IllegalStateException.class,()->new PaymentQrFunction(order,tenant).generatePaymentQr().apply(new PaymentQrFunction.PaymentQrRequest(t,UUID.randomUUID(),id,BigDecimal.ONE,"BTN","R")));}
 @Test void rejectsOrderThatIsNotAwaitingPayment(){UUID t=UUID.randomUUID(),o=UUID.randomUUID(),id=UUID.randomUUID();OrderTrustPort order=mock(OrderTrustPort.class);TenantPaymentDetailsPort tenant=mock(TenantPaymentDetailsPort.class);when(order.get(id,t)).thenReturn(new OrderTrustPort.OrderDetails(id,t,BigDecimal.ONE,"BTN","CONFIRMED","R"));when(tenant.get(t,o)).thenReturn(new TenantPaymentDetailsPort.PaymentDetails(t,o,"Bank","ACC",""));assertThrows(IllegalStateException.class,()->new PaymentQrFunction(order,tenant).generatePaymentQr().apply(new PaymentQrFunction.PaymentQrRequest(t,o,id,BigDecimal.ONE,"BTN","R")));}}
